export const round=(x,d=2)=>Math.round((x+Number.EPSILON)*10**d)/10**d;
export function validDate(value){if(typeof value!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;const d=new Date(value+'T12:00:00Z');return Number.isFinite(+d)&&d.toISOString().slice(0,10)===value;}
export function previousDate(value){if(!validDate(value))return '';const d=new Date(value+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-1);const result=d.toISOString().slice(0,10);return validDate(result)?result:'';}
export function eventDates(event){return {eventDate:event.date||'',receiptDate:event.receiptDate||'',orderDate:previousDate(event.receiptDate)};}
export function costTotal(items){return items.reduce((sum,r)=>sum+Math.round(Number(r.qty||0)*Number(r.price||0)*100),0)/100}
export function travelCalc(t){const liters=Number(t.liters),rate=Number(t.rate);if(!(Number.isFinite(liters)&&Number.isFinite(rate)&&liters>0&&rate>0))return {error:'Вкажіть витрачене пальне та норму витрати більше нуля.'};const total=round(liters/rate*100+Number(t.adjustmentKm||0),2);if(!(total>0))return {error:'Поправка не може зменшити пробіг до нуля або нижче.'};let sum=0,fuelSum=0;const rows=t.rows.map((r,i)=>{const km=i===t.rows.length-1?round(total-sum):Number(r.km||0);sum=round(sum+km);const fuel=i===t.rows.length-1?round(liters-fuelSum):round(km/total*liters);fuelSum=round(fuelSum+fuel);return {...r,km,fuel}});if(!rows.length)return {error:'Додайте хоча б одну поїздку.'};if(rows.some(r=>!Number.isFinite(r.km)||r.km<0||r.fuel<0))return {error:'Пробіг поїздок перевищує доступний. Зменште кілометри або збільште витрачене пальне.'};const refill=t.endTarget!==undefined?round(liters+Number(t.endTarget)-Number(t.startFuel||0)):Number(t.refill||0);const endFuel=round(Number(t.startFuel||0)+refill-liters);return {total,rows,refill,endFuel,endOdo:round(Number(t.odometer||0)+total),normFuel:round(total*rate/100),actualRate:round(liters/total*100,4),fuelDifference:round(liters-total*rate/100),error:refill<0?'Розраховане видане пальне від’ємне. Збільште кінцевий залишок або перевірте витрату.':endFuel<0?'Недостатньо пального: перевірте початковий залишок і заправку.':''}}
